parameters.functionCode:
// Extract pricing query parameters
const serviceName = $json.body.serviceName || '';
const serviceCategory = $json.body.serviceCategory || ''; // 'consulta', 'vacuna', 'procedimiento', etc.
const searchQuery = $json.body.searchQuery || ''; // Free text search

return {
  json: {
    serviceName: serviceName.toLowerCase().trim(),
    serviceCategory: serviceCategory.toLowerCase().trim(),
    searchQuery: searchQuery.toLowerCase().trim(),
    sessionId: $json.body.sessionId,
    userId: $json.body.userId
  }
};

// Parse Google Sheets data and search for matching services
const sheetData = $json; // Array of rows from Google Sheets
const serviceName = $input.first().json.serviceName;
const serviceCategory = $input.first().json.serviceCategory;
const searchQuery = $input.first().json.searchQuery;

// Assume sheet structure: Category | Service Name | Description | Price | Notes
// First row is header, so skip it
const services = [];

if (Array.isArray(sheetData) && sheetData.length > 1) {
  for (let i = 1; i < sheetData.length; i++) {
    const row = sheetData[i];
    if (!row || row.length < 4) continue;

    const service = {
      category: (row[0] || '').toString().toLowerCase().trim(),
      name: (row[1] || '').toString().toLowerCase().trim(),
      description: (row[2] || '').toString().trim(),
      price: (row[3] || '').toString().trim(),
      notes: (row[4] || '').toString().trim()
    };

    // Search logic
    let matches = false;

    // If specific service name is provided
    if (serviceName && service.name.includes(serviceName)) {
      matches = true;
    }

    // If category is specified
    if (serviceCategory && service.category.includes(serviceCategory)) {
      matches = true;
    }

    // If free text search
    if (searchQuery) {
      if (service.name.includes(searchQuery) || 
          service.description.toLowerCase().includes(searchQuery) ||
          service.category.includes(searchQuery)) {
        matches = true;
      }
    }

    // If no filters provided, return all
    if (!serviceName && !serviceCategory && !searchQuery) {
      matches = true;
    }

    if (matches) {
      services.push({
        category: row[0],
        name: row[1],
        description: service.description,
        price: service.price,
        notes: service.notes
      });
    }
  }
}

return {
  json: {
    matchedServices: services,
    totalMatches: services.length,
    searchCriteria: {
      serviceName,
      serviceCategory,
      searchQuery
    }
  }
};

// Format pricing response for user-friendly display
const services = $json.matchedServices || [];

if (services.length === 0) {
  return {
    json: {
      success: true,
      found: false,
      message: "No encontré información de precios para ese servicio. ¿Podrías ser más específico o preguntar por otro servicio?",
      suggestions: [
        "Consulta pediátrica general",
        "Control de niño sano",
        "Vacunas",
        "Consulta de urgencia"
      ]
    }
  };
}

// Format single or multiple results
let formattedMessage = "";

if (services.length === 1) {
  const service = services[0];
  formattedMessage = `📋 **${service.name}**\n\n`;
  if (service.description) {
    formattedMessage += `${service.description}\n\n`;
  }
  formattedMessage += `💰 **Precio:** ${service.price}`;
  if (service.notes) {
    formattedMessage += `\n\n📝 *Nota:* ${service.notes}`;
  }
} else {
  formattedMessage = `Encontré ${services.length} servicios relacionados:\n\n`;
  services.forEach((service, index) => {
    formattedMessage += `${index + 1}. **${service.name}**\n`;
    formattedMessage += `   💰 ${service.price}`;
    if (service.notes) {
      formattedMessage += ` - ${service.notes}`;
    }
    formattedMessage += `\n\n`;
  });
}

formattedMessage += "\n\n¿Te gustaría agendar una cita o tienes alguna otra pregunta?";

return {
  json: {
    success: true,
    found: true,
    message: formattedMessage,
    services: services,
    totalResults: services.length
  }
};

